		return f32( f32( f32( s * roundTiesToEven( f32( f32( mod / FLOAT16_MIN ) / FLOAT16_EPSILON ) ) ) * FLOAT16_MIN ) * FLOAT16_EPSILON ); // eslint-disable-line max-len
